#include "recovery_journal.h"
#include <string.h>
#define RJ_SIZE 301u
static ps_result save(const ps_io *i,const rj_record *r){unsigned char p[RJ_SIZE]={0};memcpy(p,"HSJ1",4);p[4]=1;p[5]=(unsigned char)r->unresolved;ps_put64(p+8,r->incarnation);ps_put64(p+16,r->last_token);ps_put64(p+24,r->attach_incarnation);ps_put64(p+32,r->token);if(r->unresolved)ps_encode_identity(p+40,&r->identity);ps_seal(p,sizeof(p));return ps_atomic_write(i,"recovery.v1",p,sizeof(p));}
ps_result rj_boot(const ps_io *i,rj_record *out){unsigned char p[PS_MAX_RECORD];size_t n=0;int read; rj_record r={0};ps_result result;if(!ps_io_valid(i)||!out)return PS_INVALID;memset(out,0,sizeof(*out));read=i->read(i->context,"recovery.v1",p,sizeof(p),&n);if(read<0||read>1)return PS_IO_ERROR;if(read==1){unsigned j;if(n!=RJ_SIZE||memcmp(p,"HSJ1",4)||p[4]!=1||p[5]>1||p[6]||p[7]||!ps_sealed(p,n))return PS_CORRUPT;r.unresolved=p[5];r.incarnation=ps_get64(p+8);r.last_token=ps_get64(p+16);r.attach_incarnation=ps_get64(p+24);r.token=ps_get64(p+32);if(!r.incarnation)return PS_CORRUPT;if(r.unresolved){if(!r.token||r.token>r.last_token||!r.attach_incarnation||r.attach_incarnation>r.incarnation||!ps_decode_identity(&r.identity,p+40))return PS_CORRUPT;}else{if(r.token||r.attach_incarnation)return PS_CORRUPT;for(j=40;j<297;j++)if(p[j])return PS_CORRUPT;}}if(r.incarnation==UINT64_MAX)return PS_INVALID;r.incarnation++;result=save(i,&r);if(result==PS_OK)*out=r;return result;}
ps_result rj_intent(const ps_io *i,rj_record *r,const ap_identity *id,uint64_t *token){rj_record next;ps_result result;if(!r||!token||!ap_identity_valid(id)||!r->incarnation||r->unresolved||r->last_token==UINT64_MAX)return PS_INVALID;next=*r;next.unresolved=1;next.identity=*id;next.token=++next.last_token;next.attach_incarnation=next.incarnation;result=save(i,&next);/* Even an uncertain commit keeps conservative in-memory obligations. */*r=next;if(result==PS_OK)*token=next.token;return result;}
ps_result rj_restored(const ps_io *i,rj_record *r,const ap_identity *id,uint64_t incarnation,uint64_t token,ap_ack ack){rj_record next;ps_result result;if(!r||!r->unresolved||ack!=AP_ACK_SUCCESS||incarnation!=r->attach_incarnation||token!=r->token||!ps_identity_equal(id,&r->identity))return PS_INVALID;next=*r;next.unresolved=0;next.token=0;next.attach_incarnation=0;memset(&next.identity,0,sizeof(next.identity));result=save(i,&next);if(result==PS_OK)*r=next;return result;}
